\(\begin{array}{|l|l|l|l|}
\hline & \text { List-I } & & \text { List-II } \\
\hline \text { A } & \text { Have same speed } & \text { (p) } & 2: 1 \\
\hline \text { B } & \begin{array}{l}
\text { Have same potential } \\
\text { difference }
\end{array} & \text { (q) } & 1: 1 \\
\hline \text { C } & \begin{array}{l}
\text { Have same kinetic } \\
\text { energy. }
\end{array} & \text { (r) } & 4: 1 \\
\hline \text { D } & \begin{array}{l}
\text { Have same linear } \\
\text { momentum }
\end{array} & \text { (s) } & 2 \sqrt{2}: 1 \\
\hline
